INSERT INTO `ec_reviews` (`id`, `customer_id`, `customer_name`, `customer_email`, `product_id`, `star`, `comment`, `status`, `created_at`, `updated_at`, `images`) VALUES
(1, 2, NULL, NULL, 17, 4.00, 'Very enthusiastic support! Excellent code is written. It\'s a true pleasure working with.', 'published', '2024-10-31 16:48:34', '2024-10-31 16:48:34', '[\"products\\/12-1.jpg\",\"products\\/21-1.jpg\",\"products\\/24-1.jpg\"]'),
(2, 3, NULL, NULL, 20, 4.00, 'Clean & perfect source code', 'published', '2024-10-31 16:48:34', '2024-10-31 16:48:34', '[\"products\\/2-1.jpg\",\"products\\/24.jpg\"]'),
(3, 4, NULL, NULL, 9, 3.00, 'Solution is too robust for our purpose so we didn\'t use it at the end. But I appreciate customer support during initial configuration.', 'published', '2024-10-31 16:48:34', '2024-10-31 16:48:34', '[\"products\\/2.jpg\",\"products\\/10-1.jpg\",\"products\\/20.jpg\"]'),
(4, 4, NULL, NULL, 8, 2.00, 'It\'s not my first experience here on Codecanyon and I can honestly tell you all that Botble puts a LOT of effort into the support. They answer so fast, they helped me tons of times. REALLY by far THE BEST EXPERIENCE on Codecanyon. Those guys at Botble are so good that they deserve 5 stars. I recommend them, I trust them and I can\'t wait to see what they will sell in a near future. Thank you Botble :)', 'published', '2024-10-31 16:48:34', '2024-10-31 16:48:34', '[\"products\\/17-1.jpg\"]'),
